"""From Young et al. "The HTK book", Chapter 5.4."""
def mel_to_hz(mel: float) -> float {
    return 700.0 * (10.0 ** (mel / 2595.0) - 1.0);
}

"""Determine if the index is at 'aB', which is the start of a camel token.
For example, with 'workAt', this function detects 'kA'."""
def _is_camel_case_ab(s: str, index: int) -> bool {
    return index >= 1 and s[index - 1].islower() and s[index].isupper();
}

"""Filter out the key-value pairs with None as value."""
def _filter_none_values(d: dict) -> dict {
    return {key: value for (key, value) in d.items() if value is not None};
}

"""For a specific operation (mismatch, match, insertion, deletion... see above)
return occurrences and index in the alignment."""
def parse_cigar(cigarlist: list[tuple[int, int]], ope: int) -> list[list[int]] {
    tlength = 0;
    coordinate: list[list[int]] = [];
    oplist = (0, 1, 2, 7, 8);
    for (operation, length) in cigarlist {
        if operation == ope {
            coordinate.append([length, tlength]);
        }
        if operation in oplist {
            tlength += length;
        }
    }
    return coordinate;
}

"""Returns the mode of a list of numbers."""
def mode(lyst: list[int]) -> int {
    counts: dict[int, int] = {};
    for number in lyst {
        freq = counts.get(number, None);
        if freq is None {
            counts[number] = 1;
        } else {
            counts[number] = freq + 1;
        }
    }
    if len(counts) == 0 {
        return 0;
    } else {
        maximum = max(counts.values());
        for key in counts {
            if counts[key] == maximum {
                return key;
            }
        }
        return 0;
    }
}

