}

"""fitness_function(solution, answer) Returns a fitness score of a solution compaired to the desired answer. This score is the absolute 'ascii' distance between characters."""
def fitness_function(solution: bytes, answer: bytes) -> int {
    return sum(abs(solution[i] - answer[i]) for i in range(len(answer)));
}

"""Find indexes of desired values from filterOne or filterTwo in lst."""
def getHeaders(lst: list[object], filterOne: list[object], filterTwo: list[object]) -> list[int] {
    headers = [];
    for (i, value) in enumerate(filterOne) {
        if value in lst {
            headers.append(lst.index(value));
        } else {
            headers.append(lst.index(filterTwo[i]));
        }
    }
    return headers;
}

"""
	evaluations(ty, pv) -> ACC

	Calculate accuracy using the true values (ty) and predicted values (pv).
	"""
def evaluations(ty: list[int], pv: list[int]) -> float {
    if len(ty) != len(pv) {
        raise ValueError("len(ty) must equal to len(pv)");
    }
    total_correct = 0;
    for (v, y) in zip(pv, ty) {
        if y == v {
            total_correct += 1;
        }
    }
    return 100.0 * total_correct / len(ty);
}

"""Decode a BIOES tag sequence into entity spans."""
def decode_from_bioes(tags: list[str | None]) -> list[dict[str, int | str | None]] {
    res = [];
    ent_idxs = [];
    cur_type: str | None = None;
    def flush() {
        if len(ent_idxs) > 0 {
            res.append({'start': ent_idxs[0], 'end': ent_idxs[-1], 'type': cur_type});
        }
    }
    for (idx, tag) in enumerate(tags) {
        if tag is None {
            tag = 'O';
        }
        if tag == 'O' {
            flush();
            ent_idxs = [];
        } elif tag.startswith('B-') {
            flush();
            ent_idxs = [idx];
            cur_type = tag[2:];
        } elif tag.startswith('I-') {
            ent_idxs.append(idx);
            cur_type = tag[2:];
        } elif tag.startswith('E-') {
            ent_idxs.append(idx);
            cur_type = tag[2:];
            flush();
            ent_idxs = [];
        } elif tag.startswith('S-') {
            flush();
            ent_idxs = [idx];
            cur_type = tag[2:];
            flush();
            ent_idxs = [];
        }
    }
    flush();
    return res;
}

