""" parses the tags and repos from a image_results with the format:
{
     'image': [{
           'pluginImage': {
            'ibmContainerRegistry': 'internalRepo/name'
               'publicRegistry': 'repo/name'
           },
              'driverImage': {
                  'ibmContainerRegistry': 'internalRepo/name'
               'publicRegistry': 'repo/name'
          },
               'pluginBuild': 'X.X.X',
               'driverBuild': 'X.X.X',
            'pullPolicy': 'Always'
        }],
       'pluginImage': [{EXACT SAME CONTENTS AS ABOVE}],
    'driverImage': [{EXACT SAME CONTENTS AS ABOVE}]
}

        Current known apps with this format:
            ibm-object-storage-plugin
    """
def parse_both_2(image_results: dict[str, list[dict[str, str | dict[str, str]]]]) -> tuple[list[str], list[str]] {
    tags = [];
    repos = [];
    image_info = image_results['image'][0];
    for (k, v) in image_info.items() {
        if "Build" in k {
            tags.append(v);
        } elif "Image" in k {
            repos.append(v['publicRegistry']);
        }
    }
    return (tags, repos);
}

"""ip to number """
def i2n(i: str) -> int {
    ip = [int(x) for x in i.split('.')];
    return ip[0] << 24 | ip[1] << 16 | ip[2] << 8 | ip[3];
}

"""
    Sorts a list using bubble sort algorithm.

    Input: A list of integers.
    Output: A list containing the same integers as the input, but sorted in
            ascending order.
    """
def bubble_sort(array: list[int]) -> list[int] {
    for z in range(len(array) - 1) {
        for x in range(len(array) - 1) {
            for y in range(len(array) - 1) {
                if array[x] > array[x + 1] {
                    temp = array[x];
                    array[x] = array[x + 1];
                    array[x + 1] = temp;
                }
            }
        }
    }
    return array;
}

"""Filter that converts a duration in seconds to something like 01:54:01"""
def duration(duration: int | str | None) -> str {
    if duration is None {
        return '';
    }
    duration = int(duration);
    seconds = duration % 60;
    minutes = (duration // 60) % 60;
    hours = duration // 60 // 60;
    s = '%02d' % seconds;
    m = '%02d' % minutes;
    h = '%02d' % hours;
    output = [];
    if hours > 0 {
        output.append(h);
    }
    output.append(m);
    output.append(s);
    return ':'.join(output);
}

