"""See setCounters() / getCounters() methods in IJ source, ij/gui/PointRoi.java."""
def get_counter(data: list[int], base: int) -> tuple[int, int] {
    _ = data[base];
    b1 = data[base + 1];
    b2 = data[base + 2];
    b3 = data[base + 3];
    counter = b3;
    position = (b1 << 8) + b2;
    return (counter, position);
}

"""Given a list of integers, creates a list of ranges with the consecutive numbers found in the list."""
def get_residue_ranges(numbers: list[int]) -> list[tuple[int, int]] {
    nums = sorted(set(numbers));
    gaps = [
        [s, e]
        for (s, e) in zip(nums, nums[1:])
        if s + 3 < e
    ];
    edges = iter(nums[:1] + sum(gaps, []) + nums[-1:]);
    return list(zip(edges, edges));
}

"""
    NAIVE VERSION!
    Find minimum number of characters required to make a String Palindromic
    NOTE:The only operation allowed is to insert characters in the beginning
    of the string. Return the number of characters that are needed to be
    inserted to make the string a palindrome string.
    Rutime: O(n^2)
    Args:
        text(str): given string
    Returns:
        num of chars(int): min required chars to make a string palindromic
    """
def min_required_char(text: str) -> int {
    if not text {
        return 0;
    }
    left = 0;
    right = len(text) - 1;
    sliding_window = 2;
    while left <= right {
        if text[left] != text[right] {
            right = len(text) - sliding_window;
            print(f"right: {right}");
            left = 0;
            print(f"left: {left}");
            sliding_window += 1;
        } else {
            right -= 1;
            left += 1;
        }
    }
    return sliding_window - 2;
}

