"""
    Note: See http://info.geonet.org.nz/display/appdata/Accelerogram+Data+Filenames+and+Formats
    The file name can take three forms:
    XNNSITEJJ, where X is the instrument code1, NN is the two-digit year
    of acquisition, SITE is the 4 character site code, and JJ is the site's
    unique accelerogram number for that year.
    YYYYMMDD_HHMM_SITE, where YYYY/MM/DD HH:MM is the earthquake origin time
    (UTC) and SITE is the 3 or 4 character site code.
    YYYYMMDD_HHMM_SITE_XX, where YYYY/MM/DD HH:MM is the instrument trigger time
    (UTC), SITE is the 3 or 4 character site code, and XX is the sensor location
    code. The latter is most appropriate for arrays of borehole sensors.

    fname: name of geoNet data file, must not include path
    """
def parse_V1A_fname(fname: str) -> tuple[str, str, str] {
    form1 = "XNNSITEJJ";
    form2 = "YYYYMMDD_HHMM_SITE";
    form3 = "YYYYMMDD_HHMM_SITE_XX";
    fname = fname.split(".")[0];
    YYYYMMDD = "";
    HHMM = "";
    if fname.count("_") == form1.count("_") {
        stat_code = fname[3:7];
    } elif fname.count("_") == form2.count("_") {
        (YYYYMMDD, HHMM, stat_code) = fname.split("_");
    } elif fname.count("_") == form3.count("_") {
        (YYYYMMDD, HHMM, stat_code, XX) = fname.split("_");
    } else {
        raise Exception(
            "{:s} is unknow file name format for .V1A files\n".format(fname)
        );
    }
    return (YYYYMMDD, HHMM, stat_code);
}

"""Given a mapping of package_data that contains a version and may an epoch and
release, return a complete version."""
def get_full_version(package_data: dict[str, str]) -> str {
    version = package_data['version'];
    release = package_data.get('release', '');
    if release {
        release = f'-{release}';
    }
    epoch = package_data.get('epoch', '');
    if epoch {
        epoch = f'{epoch}~';
    }
    version = f'{epoch}{version}{release}';
    return version;
}

"""Get string defining the border mode."""
def padding_string(pad: tuple[int, int], pool_size: list[int]) -> str {
    if pad == (0, 0) {
        padding = 'valid';
    } elif pad == (pool_size[0] // 2, pool_size[1] // 2) {
        padding = 'same';
    } elif pad == (pool_size[0] - 1, pool_size[1] - 1) {
        padding = 'full';
    } else {
        raise NotImplementedError(
            "Padding {} could not be interpreted as any of the ".format(pad)
            + "supported border modes 'valid', 'same' or 'full'."
        );
    }
    return padding;
}

"""Check for expected but missing keyword arguments and raise TypeError,
else return the keyword arguments repackaged in a dictionary (the payload).
"""
def process_kwargs(
    expected_keys: list[str],
    kwargs: dict[str, str | int | float | bool],
) -> dict[str, str | int | float | bool] {
    payload = {};
    for key in expected_keys {
        value = kwargs.pop(key, False);
        if not value {
            raise TypeError("Missing keyword argument: %s" % key);
        }
        payload[key] = value;
    }
    return payload;
}

