"""Convert the random numbers into a 4 digit int."""
def numCreator(a: int, b: int, c: int, d: int) -> int {
    output = a * 1000 + b * 100 + c * 10 + d;
    return int(output);
}

"""Make damage list from result; build damage date list from score data."""
def make_damage_list(find_list: list[list[int]], damage: list[str]) -> bool {
    ret = False;
    temp_list: list[int] = [];
    for row in find_list {
        if row[0] != 0 {
            if not temp_list {
                temp_list = row;
                ret = True;
            }
            if row[0] > temp_list[0] + 5 {
                damage.append(str(temp_list[1]));
                temp_list = row;
            } elif row[2] > temp_list[2] {
                temp_list = row;
            }
        }
    }
    if ret {
        damage.append(str(temp_list[1]));
    }
    return ret;
}

"""
Extracts a list of transitions from a sequence, returning a list of lists containing each transition.
"""
def get_transitions(sequence: list[int]) -> list[list[int]] {
    return [[sequence[position], sequence[position + 1]] for position in range(len(sequence) - 1) if sequence[position] != sequence[position + 1]];
}

