"""Recursively convert inputs to uppercase strings, except if None."""
def to_upper(inp: str | list | None) -> str | list | None {
    if inp is None {
        return None;
    }
    if isinstance(inp, list) {
        return [to_upper(s) for s in inp];
    }
    return str(inp).upper();
}

"""Ensure column name is safe for SQL."""
def safe_col_name(args_pair: tuple[int, str]) -> str {
    (idx, col) = args_pair;
    col = col.strip().replace(' ', '_').replace('.', '_').replace(',', '_');
    return str(idx) if col == '' else col;
}

"""Simplifies list of snapshots by retaining snapshot name and creation time only."""
def get_snapshots_list(response: dict[str, list[dict[str, object]]], is_aurora: bool) -> dict[str, object] {
    snapshots = {};
    response_list_key = "DBClusterSnapshots" if is_aurora else "DBSnapshots";
    identifier_list_key = "DBClusterSnapshotIdentifier" if is_aurora else "DBSnapshotIdentifier";
    for snapshot in response[response_list_key] {
        if snapshot["Status"] != "available" {
            continue;
        }
        snapshots[snapshot[identifier_list_key]] = snapshot["SnapshotCreateTime"];
    }
    return snapshots;
}

"""converts matrix indices so all are below the diagonal

    cells: list of indices into a 2D integer-indexable object
     (typically a list or lists of array of arrays)

    """
def get_ltm_cells(cells: list[tuple[int, int]]) -> list[tuple[int, int]] {
    new_cells = [];
    for (i, j) in cells {
        if i == j {
            continue;
        }
        if i < j {
            (i, j) = (j, i);
        }
        new_cells.append((i, j));
    }
    return sorted(set(new_cells));
}

