"""Return the day count when a growing plant reaches the desired height."""
def growing_plant(upSpeed: int, downSpeed: int, desiredHeight: int) -> int {
    height = 0;
    days = 0;
    while height <= desiredHeight {
        height += upSpeed;
        days += 1;
        if height >= desiredHeight {
            return days;
        }
        height -= downSpeed;
    }
    return days;
}

"""
For this exercise you can assume numerator and denominator are of type int/str/float.
Try to convert numerator and denominator to int types, if that raises a ValueError reraise it.
Following do the division and return the result.
However if denominator is 0 catch the corresponding exception Python throws (cannot divide by 0), and return 0.
"""
def divide_numbers(numerator: int | str | float, denominator: int | str | float) -> float | int {
    num: int;
    den: int;
    try {
        num = int(numerator);
        den = int(denominator);
    } except ValueError {
        raise;
    }
    try {
        return num / den;
    } except ZeroDivisionError {
        return 0;
    }
}

