"""Returns the interpolated y_value for given x_value using sorted x_array and y_array."""
def linearly_interpolate_point(x_array: list[float], y_array: list[float], x_value: float) -> float {
    lower_index: int | None = None;
    for (index, x) in enumerate(x_array) {
        if x > x_value {
            break;
        }
        lower_index = index;
    }
    idx: int = 0;
    if lower_index is not None {
        idx = lower_index as int;
    }
    if idx == len(x_array) - 1 {
        idx = idx - 1;
    }
    higher_index = idx + 1;
    dydx = (y_array[higher_index] - y_array[idx]) / (x_array[higher_index] - x_array[idx]);
    if x_value < x_array[idx] {
        y_value = y_array[idx] - dydx * (x_value - x_array[idx]);
    } else {
        y_value = y_array[idx] + dydx * (x_value - x_array[idx]);
    }
    return y_value;
}

"""Rotates a set of points in 2D space by r*90 degrees."""
def rotate_blocks(blocks: list[tuple[int, int]], r: int) -> list[tuple[int, int]] {
    r = r % 4;
    if r == 0 {
        return blocks;
    }
    for (i, block) in enumerate(blocks) {
        if r == 1 {
            blocks[i] = (-block[1], block[0]);
        } elif r == 2 {
            blocks[i] = (-block[0], -block[1]);
        } elif r == 3 {
            blocks[i] = (block[1], -block[0]);
        }
    }
    return blocks;
}

