                    }
                }
            }
        }
    }
    return True;
}

"""Return the field and dtype parts of attribute_field; default dtype is \"str\"."""
def get_field_and_dtype_from_attribute_field(attribute_field: str | dict[str, str | dict]) -> tuple[str | dict[str, str | dict], str] {
    if type(attribute_field) == type({}) {
        if "$const" in attribute_field {
            (field, dtype) = get_field_and_dtype_from_attribute_field(attribute_field["$const"]);
        } elif "$field" in attribute_field {
            (field, dtype) = get_field_and_dtype_from_attribute_field(attribute_field["$field"]);
        } else {
            (field, dtype) = (attribute_field, "str");
        }
    } elif isinstance(attribute_field, str) {
        if "," in attribute_field {
            (field, dtype) = attribute_field.split(",");
            (field, dtype) = (field.strip(), dtype.strip());
        } else {
            (field, dtype) = (attribute_field.strip(), "str");
        }
    }
    return (field, dtype);
}

