"""
  Returns the nth term of the Fibonacci Sequence
  n is zero based indexed
  """
def Fibonacci(n: int) -> int {
    if n < 0 {
        raise Exception("Invalid Argument");
    } elif n < 2 {
        return n;
    }
    return Fibonacci(n - 1) + Fibonacci(n - 2);
}

