    xd2 = (coord1[0] - coord2[0]) ** 2;
    yd2 = (coord1[1] - coord2[1]) ** 2;
    zd2 = (coord1[2] - coord2[2]) ** 2;
    return (xd2 + yd2 + zd2) ** 0.5;
}

"""Finds all paths between 2 nodes in a graph using BFS."""
def bfsAllPaths(
    graph: dict[str, list[str]], start: str, goal: str
) -> list[str] | list[list[str]] {
    path = [start];
    if start == goal {
        return path;
    }
    solutions = [];
    explored = [];
    queue = [];
    queue.append(path);
    while len(queue) > 0 {
        path = queue.pop(0);
        `node = path[-1];
        if `node not in explored {
            explored.append(`node);
            neighbours = graph.get(`node, []);
            for neighbour in neighbours {
                path1 = path[:];
                path1.append(neighbour);
                if neighbour == goal {
                    solutions.append(path1);
                } else {
                    queue.append(path1);
                }
            }
        }
    }
    return solutions;
}

