"""Returns a tuple of the active firmware's configuration."""
def find_active_firmware(boot_config_sector: bytes) -> tuple[int | None, int | None, int | None] {
    for i in range(8) {
        app_entry = boot_config_sector[i * 32:i * 32 + 32];
        config_flags = int.from_bytes(app_entry[0:4], 'big');
        if (config_flags & 1) != 1 {
            continue;
        }
        app_address = int.from_bytes(app_entry[4:8], 'big');
        app_size = int.from_bytes(app_entry[8:12], 'big');
        return (app_address, app_size, i);
    }
    return (None, None, None);
}

"""Generate the nth Van der Corput number."""
def _corput(index: int, base: int) -> float {
    x = 0.0;
    norm = 1.0 / base;
    while index > 0 {
        x += (index % base) * norm;
        index //= base;
        norm /= base;
    }
    return x;
}

"""
Computes overall formula features score.

It discriminates the contributions between features. Semantic and
structural features are more important than constant and variable
features and thus given more weights.
"""
def compute_total_matching_score(
    sem_score_norm: float,
    struc_score_norm: float,
    cn_score_norm: float,
    var_score_norm: float,
    a: float = 0.2
) -> float {
    return (
        (1 - a) * (sem_score_norm + struc_score_norm)
        + a * (cn_score_norm + var_score_norm)
    ) / 2.0;
}

