"""return (cnt_K, cnt_R,  per_K, per_R)"""
def GetKRStateFraction(alignedSeqList: list[str]) -> tuple[list[int], list[int], list[float], list[float]] {
    length_alignment = len(alignedSeqList[0]);
    num_seq = len(alignedSeqList);
    cnt_K = [0] * length_alignment;
    cnt_R = [0] * length_alignment;
    for aligned_seq in alignedSeqList {
        for j in range(length_alignment) {
            s = aligned_seq[j];
            if s == 'K' {
                cnt_K[j] += 1;
            } elif s == 'R' {
                cnt_R[j] += 1;
            }
        }
    }
    per_K = [0.0] * length_alignment;
    per_R = [0.0] * length_alignment;
    num_seq_float = float(num_seq);
    for j in range(length_alignment) {
        per_K[j] = cnt_K[j] / num_seq_float;
        per_R[j] = cnt_R[j] / num_seq_float;
    }
    return (cnt_K, cnt_R, per_K, per_R);
}

