"""
A method that calculates the largest square filled with only 1's of a given binary matrix (space-optimized 2/2).
Problem description: https://practice.geeksforgeeks.org/problems/largest-square-formed-in-a-matrix/0
    time complexity: O(n*m)
    space complexity: O(min(n,m))

Parameters
----------
matrix : int[[]]
    a 2-dimensional list

Returns
-------
int
    size of the largest square
"""
def calculate_largest_square_filled_space_optimized2(matrix: list[list[int]]) -> int {
    n = len(matrix);
    assert n >= 1;
    m = len(matrix[0]);
    assert m >= 1;
    max_square_size = 0;
    if n < m {
        arr = [[0 for _ in range(n)], [0 for _ in range(n)]];
        for j in range(m) {
            arr[0] = [e for e in arr[1]];
            for i in range(n) {
                if matrix[i][j] == 0 {
                    arr[1][i] = 0;
                } else {
                    if j == 0 or i == 0 {
                        arr[1][i] = 1;
                    } else {
                        arr[1][i] = min(arr[0][i], arr[1][i - 1], arr[0][i - 1]) + 1;
                    }
                    max_square_size = max(arr[1][i], max_square_size);
                }
            }
        }
    } else {
        arr = [[0 for _ in range(m)], [0 for _ in range(m)]];
        for i in range(n) {
            arr[0] = [e for e in arr[1]];
            for j in range(m) {
                if matrix[i][j] == 0 {
                    arr[1][j] = 0;
                } else {
                    if i == 0 or j == 0 {
                        arr[1][j] = 1;
                    } else {
                        arr[1][j] = min(arr[0][j], arr[1][j - 1], arr[0][j - 1]) + 1;
                    }
                    max_square_size = max(arr[1][j], max_square_size);
                }
            }
        }
    }
    return max_square_size;
}

"""Return the sum of even-valued Fibonacci terms not exceeding limit."""
def even_fibonacci_numbers(limit: int = 4000000) -> int {
    (n1, n2) = (1, 2);
    even_sum = 0;
    while n2 <= limit {
        if n2 % 2 == 0 {
            even_sum += n2;
        }
        temp = n2 + n1;
        n1 = n2;
        n2 = temp;
    }
    return even_sum;
}

"""
Returns the median of the elements of the iterable `x`.

If the number of elements in `x` is even, the arithmetic mean of the upper
and lower median values is returned.
"""
def median(x: list[int | float]) -> int | float {
    s = sorted(x);
    n = len(s);
    if n % 2 == 1 {
        return s[(n - 1) // 2];
    }
    m = n // 2;
    return 0.5 * (s[m - 1] + s[m]);
}

