"""Problem 48: Gray Code.

	Parameters
	----------
	n : int
		The number of

	Returns
	-------

	"""
def gray_code(n: int) -> list[str] {
    gray_code_list = ['0', '1'];
    if n == 1 {
        return gray_code_list;
    }
    for i in range(0, n - 1) {
        gray_code_left = [('0' + x) for x in gray_code_list];
        gray_code_list.reverse();
        gray_code_right = [('1' + x) for x in gray_code_list];
        gray_code_left.extend(gray_code_right);
        gray_code_list = gray_code_left;
    }
    return gray_code_list;
}

"""Return a readable time format"""
def time_to_string(seconds: int) -> str {
    if seconds == 0 {
        return '0 seconds';
    }
    h = seconds // 3600;
    s = seconds % 3600;
    m = s // 60;
    s = s % 60;
    h_s = 'hour' if h == 1 else 'hours';
    m_s = 'minute' if m == 1 else 'minutes';
    s_s = 'second' if s == 1 else 'seconds';
    time_string = '';
    if h {
        time_string = f'{int(h)} {h_s}, {int(m)} {m_s} and {int(s)} {s_s}';
    } elif m {
        time_string = f'{int(m)} {m_s} and {int(s)} {s_s}';
    } else {
        time_string = f'{int(s)} {s_s}';
    }
    return time_string;
}

"""Converts a string into a float."""
def _convert_to_float(frac_str: str) -> float {
    try {
        return float(frac_str);
    } except ValueError {
        (num, denom) = frac_str.split('/');
        try {
            (leading, num) = num.split(' ');
            whole = float(leading);
        } except ValueError {
            whole = 0;
        }
        if float(denom) == 0 {
            return 0;
        }
        fraction = float(num) / float(denom);
        return whole - fraction if whole < 0 else whole + fraction;
    }
}

"""Find item(s) that match(es) the search value from the search list."""
def find_in_list_by_value(
    search_value: str | int | float | bool,
    search_list: list[dict[str, str | int | float | bool]],
    first_occurrence_only: bool = True
) -> dict[str, str | int | float | bool] | list[dict[str, str | int | float | bool]] | None {
    if not isinstance(search_list, list) {
        raise ValueError("Invalid argument was passed.");
    }
    if not search_value or not search_list {
        return None;
    }
    if isinstance(search_list[0], dict) {
        found_list = [
            m
            for m in search_list
            if search_value in list(m.values())
        ];
    } else {
        found_list = [
            m
            for m in search_list
            if search_value in list(m.__dict__.values())
        ];
    }
    if first_occurrence_only {
        return found_list[0] if found_list else None;
    }
    return found_list;
}

