"""Returns true if g1 strictly dominates g2 with the given relaxation."""
def does_strict_dominate(
    g1: tuple[float, ...],
    g2: tuple[float, ...],
    delta1: tuple[float, ...],
    delta2: tuple[float, ...]
) -> bool {
    return all(
        g2[i] + delta2[i] > g1[i] - delta1[i]
        for i in range(len(g1))
    );
}

