"""
def equal_species(list1: list[str], list2: list[str]) -> bool | int {
    if len(list1) == len(list2) {
        if len(list1) == 1 {
            return list1[0] in list2[0] or list2[0] in list1[0];
        } elif len(list1) == 2 {
            match_diag = list1[0] in list2[0] or list2[0] in list1[0];
            match_diag2 = list1[1] in list2[1] or list2[1] in list1[1];
            match_cross = list1[0] in list2[1] or list2[0] in list1[1];
            match_cross2 = list1[1] in list2[0] or list2[1] in list1[0];
            return (match_diag and match_diag2) or (match_cross and match_cross2);
        } else {
            return 0;
        }
    } else {
        return 0;
    }
}

