"""
Zimmermann function: a non-continuous function, Equation (24-26) of [2]

minimum is f(x)=0.0 at x=(7.0,2.0)
"""
def zimmermann(x: tuple[float, float]) -> float {
    (x0, x1) = x;
    f8 = 9 - x0 - x1;
    c0 = 0.0;
    c1 = 0.0;
    c2 = 0.0;
    c3 = 0.0;
    if x0 < 0 {
        c0 = -100 * x0;
    }
    if x1 < 0 {
        c1 = -100 * x1;
    }
    xx = (x0 - 3.0) * (x0 - 3) + (x1 - 2.0) * (x1 - 2);
    if xx > 16 {
        c2 = 100 * (xx - 16);
    }
    if x0 * x1 > 14 {
        c3 = 100 * (x0 * x1 - 14.0);
    }
    return max(f8, c0, c1, c2, c3);
}

