"""
    Get attributes cutting threshold

    Parameters
    ----------
    alist
        Sorted attributes list
    decreasing_factor
        Decreasing factor of the algorithm
    min_activity_count
        Minimum number of activities to include
    max_activity_count
        Maximum number of activities to include

    Returns
    ---------
    threshold
        Activities cutting threshold
    """
def get_attributes_threshold(
    alist: list[tuple[str, float]],
    decreasing_factor: int | float,
    min_activity_count: int = 1,
    max_activity_count: int = 25
) -> float {
    index = max(0, min(min_activity_count - 1, len(alist) - 1));
    threshold = alist[index][1];
    index = index + 1;
    for i in range(index, len(alist)) {
        value = alist[i][1];
        if value > threshold * decreasing_factor {
            threshold = value;
        }
        if i >= max_activity_count {
            break;
        }
    }
    return threshold;
}

"""Intermediate values take on the value associated with the next lower x-coordinate (also called a step-wise function). The last two points of a discrete graphical function must have the same y value.
Out-of-range values are the same as the closest endpoint (i.e, no extrapolation is performed)."""
def lookup_discrete(x: float, xs: list[float], ys: list[float]) -> float {
    for index in range(len(xs)) {
        if x < xs[index] {
            return ys[index - 1] if index > 0 else ys[index];
        }
    }
    return ys[len(ys) - 1];
}

