"""
    O(n*log(n))
    """
def overlapping_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]] {
    length = len(intervals);
    if length < 2 {
        return intervals;
    }
    intervals.sort(key=lambda (iv: tuple[int, int]) { iv[0]; });
    return_list = [intervals[0]];
    for i in range(1, length) {
        if return_list[-1][1] >= intervals[i][0] {
            return_list[-1] = (
                return_list[-1][0],
                max(return_list[-1][1], intervals[i][1])
            );
            break;
        } else {
            return_list.append(intervals[i]);
        }
    }
    return return_list;
}

"""Calculate the number of characters that differ between two strings of identical length.

    Returns 1 if lengths do not match.
    """
def string_distance(s1: str, s2: str) -> int {
    if len(s1) != len(s2) {
        return 1;
    }
    return sum(1 for (c1, c2) in zip(s1, s2) if c1 != c2);
}

