"""Create a usable config from the wandb config format."""
def from_wandb_format(config: dict[str, dict | str | int | float | bool | list | None]) -> dict[str, dict | str | int | float | bool | list | None] {
    wandb_config = {};
    for (key, value) in config.items() {
        if '.' in key {
            sub_keys = key.split('.');
            curr_dict = wandb_config;
            for sub_key in sub_keys[:-1] {
                if sub_key not in curr_dict {
                    curr_dict[sub_key] = {};
                }
                curr_dict = curr_dict[sub_key];
            }
            if isinstance(value, dict) and 'value' in value {
                curr_dict[sub_keys[-1]] = value['value'];
            } else {
                curr_dict[sub_keys[-1]] = value;
            }
        } elif isinstance(value, dict) and 'value' in value {
            wandb_config[key] = value['value'];
        } else {
            wandb_config[key] = value;
        }
    }
    return wandb_config;
}

"""Merges dictionaries by keys, recursing into nested dicts."""
def merge_dict(main_dict: dict[str, int | str | dict], enhance_dict: dict[str, int | str | dict]) -> dict[str, int | str | dict] {
    for (key, value) in enhance_dict.items() {
        if key not in main_dict {
            main_dict[key] = value;
        } elif isinstance(value, dict) and isinstance(main_dict[key], dict) {
            main_dict[key] = merge_dict(main_dict[key] as dict[str, int | str | dict], value as dict[str, int | str | dict]);
        } else {
            main_dict[key] = value;
        }
    }
    return main_dict;
}

"""
    Given a set of reference values and a set of test values, return
    the fraction of test values that appear in the reference set.
    If test is empty, then return None.
    """
def term_precision(reference: set[object], `test: set[object]) -> float | None {
    if not hasattr(reference, 'intersection') or not hasattr(`test, 'intersection') {
        raise TypeError('reference and test should be sets');
    }
    if len(`test) == 0 {
        return None;
    }
    return round(len(reference.intersection(`test)) / len(`test), 3);
}

"""A simple linear system of equations."""
def linear_system_example(x: list[int]) -> list[int] {
    n = len(x);
    res = [0] * n;
    for i in range(n) {
        for j in range(n) {
            res[i] += (1 + i * j) * x[j];
        }
    }
    return res;
}

