"""
Frequency bands in the microwave range are designated by letters. This
standard is the IEEE radar bands.
"""
def get_frequency_band(wavelength: float) -> str {
    ieee_freq_band_ghz = [
        ("L", 1, 2),
        ("S", 2, 4),
        ("C", 4, 8),
        ("X", 8, 12),
        ("Ku", 12, 18),
        ("K", 18, 27),
        ("Ka", 27, 40),
        ("V", 40, 75),
        ("W", 75, 110)
    ];
    ghz = 1e-9 * 300000000 / (wavelength * 0.01);
    for (band, fmin, fmax) in ieee_freq_band_ghz {
        if ghz >= fmin and ghz <= fmax {
            return band;
        }
    }
    raise ValueError("Invalid radar wavelength. Is the wavelength in cm?");
}

""" Flattens an arbitrarily large list or tuple
        Apparently very fast
        Pulled from online >> https://rightfootin.blogspot.com/2006/09/more-on-python-flatten.html
        Author: Mike C. Fletcher, Distribution: BasicTypes library.
    """
def flatten(l: list | tuple, ltypes: tuple = (list, tuple)) -> list | tuple {
    ltype = `type(l);
    l = list(l);
    i = 0;
    while i < len(l) {
        while isinstance(l[i], ltypes) {
            if not l[i] {
                l.pop(i);
                i -= 1;
                break;
            } else {
                l[i:(i + 1)] = l[i];
            }
        }
        i += 1;
    }
    return ltype(l);
}

"""Approximate fx'(x) via the five-point finite-difference stencil."""
def FivePointsDiff(fx: Callable[[float], float], x: float, h: float = 0.001) -> float {
    return (
        -fx(x + 2 * h) + 8 * fx(x + h) - 8 * fx(x - h) + fx(x - 2 * h)
    ) / (12.0 * h);
}

