"""Get the most recent status of workflow for the current PR."""
def get_status(runs: list[dict[str, str]]) -> str {
    status = 'success';
    for run in runs {
        body = run['body'];
        if "Status: " in body {
            if "Status: skipped" in body {
                continue;
            }
            if "Status: failure" in body {
                status = 'failure';
                break;
            }
            if "Status: success" in body {
                status = 'success';
                break;
            }
        } else {
            status = 'in-progress';
            break;
        }
    }
    return status;
}

