"""Sum volumes between indexes and output dates at those indexes."""
def coalesce_volume_dates(
    in_volumes: list[float],
    in_dates: list[str],
    indexes: list[int]
) -> tuple[list[float], list[str]] {
    volumes: list[float] = [];
    dates: list[str] = [];
    for i in range(len(indexes)) {
        dates.append(in_dates[indexes[i]]);
        to_sum_to = indexes[i + 1] if i + 1 < len(indexes) else len(in_volumes);
        volumes.append(sum(in_volumes[indexes[i]:to_sum_to]));
    }
    return (volumes, dates);
}

