"""Assumes left and right are sorted lists.
 lt defines an ordering on the elements of the lists.
 Returns a new sorted(by lt) list containing the same elements
 as (left + right) would contain."""
def merge(left: list[int], right: list[int], lt: Callable[[int, int], bool]) -> list[int] {
    result = [];
    (i, j) = (0, 0);
    while i < len(left) and j < len(right) {
        if lt(left[i], right[j]) {
            result.append(left[i]);
            i += 1;
        } else {
            result.append(right[j]);
            j += 1;
        }
    }
    while i < len(left) {
        result.append(left[i]);
        i += 1;
    }
    while j < len(right) {
        result.append(right[j]);
        j += 1;
    }
    return result;
}

