        if v == bad_val {
            d[k] = good_val;
        }
    }
    return d;
}

"""Partition helper function for quicksort."""
def partition(list: list[int], start: int, end: int) -> int {
    sorted = False;
    pivot = list[start];
    left = start + 1;
    right = end;
    while not sorted {
        while left <= right and list[left] <= pivot {
            left = left + 1;
        }
        while list[right] >= pivot and right >= left {
            right = right - 1;
        }
        if right < left {
            sorted = True;
        } else {
            temp = list[left];
            list[left] = list[right];
            list[right] = temp;
        }
    }
    temp = list[start];
    list[start] = list[right];
    list[right] = temp;
    return right;
}

