"""
    returns number of fractions containing a numerator with more digits than
    the denominator in the first n expansions.
    """
def solution(n: int = 1000) -> int {
    prev_numerator = 1;
    prev_denominator = 1;
    count = 0;
    for i in range(1, n + 1) {
        numerator = prev_numerator + 2 * prev_denominator;
        denominator = prev_numerator + prev_denominator;
        if len(str(numerator)) > len(str(denominator)) {
            count += 1;
        }
        prev_numerator = numerator;
        prev_denominator = denominator;
    }
    return count;
}

"""Remove duplicate letters on either end, if the are adjacent."""
def chop_duplicate_ends(word: str) -> str {
    if word[0] == word[1] {
        word = word[1:];
    }
    if word[-2:-1] == word[-1:] {
        word = word[:-1];
    }
    return word;
}

"""Fill gaps of arrays with size with indicies and elems."""
def fill_gaps[T](indicies: list[int], elementss: list[T], size: int, gap: Callable[[], T]) -> list[T] {
    full: list[T | None] = [None] * size;
    for (ind, elem) in zip(indicies, elementss) {
        full[ind] = elem;
    }
    for ind in range(size) {
        if full[ind] is None {
            full[ind] = gap();
        }
    }
    return full;
}

