"""
Given a param string and a dict of values, returns a flat dict of keyed, enumerated params.
Each dict in the values list must pertain to a single item and its data points.
"""
def enumerate_keyed_param(
    param: str,
    values: list[dict[str, str | int]] | dict[str, str | int] | tuple | set
) -> dict[str, str | int] {
    if not values {
        return {};
    }
    if not param.endswith('.') {
        param += '.';
    }
    if not isinstance(values, (list, tuple, set)) {
        values = [values];
    }
    for val in values {
        if not isinstance(val, dict) {
            raise ValueError(
                "Non-dict value detected. "
                "`values` must be a list, tuple, or set; containing only dicts."
            );
        }
    }
    params: dict[str, str | int] = {};
    for (idx, val_dict) in enumerate(values) {
        params.update(
            {
                '{param}{idx}.{key}'.format(param=param, idx=idx + 1, key=k): v
                for (k, v) in val_dict.items()
            }
        );
    }
    return params;
}

"""Flattens a list of lists to the first level.

Given a list containing a mix of scalars and lists,
flattens down to a list of the scalars within the original
list.
"""
def flatten(l: list | int | float | str | bool) -> list[int | float | str | bool] {
    if not isinstance(l, list) {
        return [l];
    }
    return sum(map(flatten, l), []);
}

"""Compare two version parts and return the difference."""
def compare_version_part(a_part: str, b_part: str) -> int {
    try {
        a_bits = a_part.split('-');
        b_bits = b_part.split('-');
        version_difference = int(a_bits[0]) - int(b_bits[0]);
        if version_difference != 0 or (len(a_bits) == 1 and len(b_bits) == 1) {
            return version_difference;
        }
        if len(a_bits) != len(b_bits) {
            return len(b_bits) - len(a_bits);
        }
        a_letter = a_bits[1][0];
        b_letter = b_bits[1][0];
        if a_letter != b_letter {
            return 0;
        }
        a_number_start = [char.isdigit() for char in a_bits[1]].index(True);
        b_number_start = [char.isdigit() for char in b_bits[1]].index(True);
        return int(a_bits[1][a_number_start:]) - int(b_bits[1][b_number_start:]);
    } except ValueError {
        return 0;
    }
}

"""Seed numpy before calling worker_init_fn."""
def _seed_npy_before_worker_init(
    worker_id: int,
    seed: int,
    worker_init_fn: Callable[[int], int | None] | None = None
) -> int | None {
    try {
        import numpy as np;
        np.random.seed(seed + worker_id);
    } except ImportError {
        ;
    }
    if worker_init_fn is not None {
        return worker_init_fn(worker_id);
    }
}

"""Plant Senescence Reflectance Index (Merzlyak et al., 1999). PSRI = (b4 - b3) / b6."""
def psri(b3: float, b4: float, b6: float) -> float {
    return (b4 - b3) / b6;
}

"""strips all white-space from a string"""
def remove_whitespace(text: str | None) -> str {
    if text is None {
        return "";
    }
    return "".join(text.split());
}

"""
    Args:
        n: number of steps of staircase
    Returns:
        Distinct ways to climb a n step staircase
    Raises:
        AssertionError: n not positive integer
    """
def climb_stairs(n: int) -> int {
    fmt = "n needs to be positive integer, your input {}";
    assert isinstance(n, int) and n > 0, fmt.format(n);
    if n == 1 {
        return 1;
    }
    dp = [0] * (n + 1);
    (dp[0], dp[1]) = (1, 1);
    for i in range(2, n + 1) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }
    return dp[n];
}

"""Convert time scale dict to seconds."""
def get_seconds(value: int | float, scale: str) -> int | float {
    scales = {
        'seconds': lambda (x: int | float) { x; },
        'minutes': lambda (x: int | float) { x * 60; },
        'hours': lambda (x: int | float) { x * 60 * 60; },
        'days': lambda (x: int | float) { x * 60 * 60 * 24; },
        'weeks': lambda (x: int | float) { x * 60 * 60 * 24 * 7; },
        'months': lambda (x: int | float) { x * 60 * 60 * 24 * 30; },
        'years': lambda (x: int | float) { x * 60 * 60 * 24 * 365; }
    };
    return scales[scale](value) as int | float;
}

"""App stop event type"""
def stop(job_id: str, event: str, action: str, resource: str, _count: int) -> tuple[str, dict[str, str]] {
    job_name = '{}:event={}:action={}'.format(resource, event, action);
    func_kwargs = dict(job_id=job_id, app_name=resource);
    return (job_name, func_kwargs);
}

"""Find bands within a target average range with enough shows."""
def find_bands(
    bands: dict[str, list[float]],
    target_avg: tuple[float, int],
    target_range: float,
    min_shows: int
) -> list[str] {
    lower_bound = target_avg[0] - target_range;
    upper_bound = target_avg[0] + target_range;
    noted_scores = target_avg[1];
    result = [];
    for (name, scores) in bands.items() {
        if len(scores) >= min_shows {
            avg = sum(scores) / len(scores) if len(scores) <= noted_scores
                else sum(scores[0:noted_scores]) / noted_scores;
            if avg >= lower_bound and avg <= upper_bound {
                result.append(name);
            }
        }
    }
    return result;
}

"""Generate sort keys according to the passed in sort key from user.

    :param model_name: Database model name be query.(alarm, meter, etc.)
    :param sort_key: sort key passed from user.
    return: sort keys list
    """
def _handle_sort_key(model_name: str, sort_key: str | None = None) -> list[str] {
    sort_keys_extra = {
        'alarm': ['name', 'user_id', 'project_id'],
        'meter': ['user_id', 'project_id'],
        'resource': ['user_id', 'project_id', 'timestamp']
    };
    sort_keys = sort_keys_extra[model_name];
    if not sort_key {
        return sort_keys;
    }
    try {
        sort_keys.remove(sort_key);
    } except ValueError {
        ;
    } finally {
        sort_keys.insert(0, sort_key);
    }
    return sort_keys;
}

"""Remove parenthesis and trailing content from a character name string."""
def stripExtra(name: str) -> str {
    start_index = name.find('(');
    if start_index == -1 or start_index == 0 {
        return name;
    }
    return name[0:(start_index - 1)];
}

"""Computes the jaccard coefficient between two sets."""
def jaccard(set1: set[object], set2: set[object]) -> int | float {
    if len(set1) == 0 or len(set2) == 0 {
        return 0;
    }
    inter = len(set1.intersection(set2));
    return inter / (len(set1) + len(set2) - inter);
}

"""Compare versions the way chrome does."""
def cmpversion(a: str, b: str) -> bool {
    def split_version(v: str) -> list[str] | tuple[str, str] {
        if '.' in v {
            return v.split('.', 1);
        }
        if '_' in v {
            return v.split('_', 1);
        }
        return (v, '0');
    }
    (a_maj, a_min) = split_version(a);
    (b_maj, b_min) = split_version(b);
    if a_maj == b_maj {
        return cmpversion(a_min, b_min);
    }
    return int(a_maj) > int(b_maj);
}

"""Format statistics for printing to a table."""
def format_stats(stats: dict[str, str | int | float]) -> str {
    result = '';
    for (key, value) in stats.items() {
        result += f'{key} - {value}\n';
    }
    return result[:-1];
}

"""m*wavelength = neff * delta_length."""
def get_mzi_delta_length(m: float, neff: float = 2.4, wavelength: float = 1.55) -> float {
    return m * wavelength / neff;
}

"""Calculates chao1 variance in absence of doubletons.

From EstimateS manual, equation 7.

chao1 is the estimate of the mean of Chao1 from the same dataset.
"""
def chao1_var_no_doubletons(singles: int | float, chao1: float) -> float {
    s = float(singles);
    return (s * (s - 1)) / 2 + (s * ((2 * s) - 1) ** 2) / 4 - (s ** 4) / (4 * chao1);
}

"""Flip the individual words in a sentence."""
def word_flipper(our_string: str) -> str {
    return " ".join([word[::-1] for word in our_string.split(" ")]);
}

"""Check that all values in given list are equal."""
def all_equal(values: list[str | int | float | bool]) -> bool {
    return all(values[0] == v for v in values);
}

"""Calculate the product of all digits in a string."""
def str_product(string: str) -> int {
    product = 1;
    for i in string {
        product *= int(i);
    }
    return product;
}
